package web

import (
	"context"
	"embed"
	"errors"
	"fmt"
	"html/template"
	"io"
	"io/fs"
	"net/http"
	"strconv"
	"strings"
	"text/template/parse"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/app"
)

//go:embed templates/*.html templates/*/*.html static/*
var assets embed.FS

var staticAssetNames = map[string]struct{}{
	"app.css": {}, "app.js": {}, "resource-monitor.css": {}, "resource-monitor.js": {},
	"run-timeline.css": {}, "run-timeline.js": {},
	"css/tokens.css": {}, "css/base.css": {}, "css/primitives.css": {}, "css/components.css": {}, "css/layouts.css": {}, "css/utilities.css": {},
	"js/app.js": {}, "js/operations.js": {}, "js/sse.js": {}, "js/study.js": {},
}

type HandlerOptions struct {
	Queries     app.WebQueries
	Operations  app.WebOperations
	Runs        app.RunUseCases
	Authority   string
	Diagnostics io.Writer
	Now         func() time.Time
	RequestID   func() string
	RootContext context.Context
	Hub         *operationHub
}

type handler struct {
	queries      app.WebQueries
	templates    *template.Template
	now          func() time.Time
	hub          *operationHub
	preparations *preparationStore
	diagnostics  io.Writer
	runs         app.RunUseCases
	qa           app.QAQueries
}

func NewHandler(opts HandlerOptions) (http.Handler, error) {
	if opts.Queries == nil {
		return nil, errors.New("web queries are required")
	}
	templates, err := parseTemplateTree(assets)
	if err != nil {
		return nil, err
	}
	if opts.Now == nil {
		opts.Now = time.Now
	}
	if opts.Diagnostics == nil {
		opts.Diagnostics = io.Discard
	}
	hub := opts.Hub
	if hub == nil {
		hub = newOperationHub(opts.RootContext, opts.Operations, opts.Now, opts.RequestID)
	}
	qa, _ := opts.Operations.(app.QAQueries)
	if qa == nil {
		qa, _ = opts.Queries.(app.QAQueries)
	}
	h := &handler{queries: opts.Queries, templates: templates, now: opts.Now, hub: hub, preparations: newPreparationStore(opts.Now, opts.RequestID), diagnostics: opts.Diagnostics, runs: opts.Runs, qa: qa}
	security := newSecurityMiddleware(opts.Authority, opts.Diagnostics, opts.Now, opts.RequestID)
	return security.wrap(h), nil
}

func parseTemplateTree(source fs.FS) (*template.Template, error) {
	if err := rejectDuplicateTemplateDefinitions(source); err != nil {
		return nil, err
	}
	templates, err := template.ParseFS(source, "templates/*.html", "templates/*/*.html")
	if err != nil {
		return nil, err
	}
	if err := validateTemplateHierarchy(templates); err != nil {
		return nil, err
	}
	return templates, nil
}

func rejectDuplicateTemplateDefinitions(source fs.FS) error {
	seen := make(map[string]string)
	var paths []string
	for _, pattern := range []string{"templates/*.html", "templates/*/*.html"} {
		matches, err := fs.Glob(source, pattern)
		if err != nil {
			return err
		}
		paths = append(paths, matches...)
	}
	for _, path := range paths {
		data, err := fs.ReadFile(source, path)
		if err != nil {
			return err
		}
		parsed, err := template.New(path).Parse(string(data))
		if err != nil {
			return fmt.Errorf("parse template %s: %w", path, err)
		}
		for _, item := range parsed.Templates() {
			name := item.Name()
			if !strings.Contains(name, "/") {
				continue
			}
			if previous := seen[name]; previous != "" {
				return fmt.Errorf("template %q is defined in both %s and %s", name, previous, path)
			}
			seen[name] = path
		}
	}
	return nil
}

func validateTemplateHierarchy(templates *template.Template) error {
	layers := map[string]int{"primitive": 0, "component": 1, "layout": 2, "page": 3}
	required := []string{
		"primitive/empty", "component/artifacts", "component/findings", "component/operation-console",
		"layout/top", "layout/bottom", "page/dashboard", "page/projects", "page/project", "page/sprint",
		"page/studies", "page/study", "page/artifact", "page/operation-confirm", "page/operation", "page/error",
	}
	for _, name := range required {
		if templates.Lookup(name) == nil {
			return fmt.Errorf("required template %q is missing", name)
		}
	}
	graph := make(map[string][]string)
	for _, item := range templates.Templates() {
		name := item.Name()
		parts := strings.SplitN(name, "/", 2)
		if len(parts) != 2 {
			continue // ParseFS also exposes empty filename roots.
		}
		level, ok := layers[parts[0]]
		if !ok {
			return fmt.Errorf("template %q has an unsupported namespace", name)
		}
		dependencies := templateDependencies(item.Tree.Root)
		for _, dependency := range dependencies {
			dependencyParts := strings.SplitN(dependency, "/", 2)
			dependencyLevel, ok := layers[dependencyParts[0]]
			if len(dependencyParts) != 2 || !ok {
				return fmt.Errorf("template %q depends on unnamespaced template %q", name, dependency)
			}
			if dependencyLevel >= level {
				return fmt.Errorf("template %q has upward or same-layer dependency %q", name, dependency)
			}
		}
		graph[name] = dependencies
	}
	visiting, visited := make(map[string]bool), make(map[string]bool)
	var visit func(string) error
	visit = func(name string) error {
		if visiting[name] {
			return fmt.Errorf("template dependency cycle includes %q", name)
		}
		if visited[name] {
			return nil
		}
		visiting[name] = true
		for _, dependency := range graph[name] {
			if err := visit(dependency); err != nil {
				return err
			}
		}
		delete(visiting, name)
		visited[name] = true
		return nil
	}
	for name := range graph {
		if err := visit(name); err != nil {
			return err
		}
	}
	return nil
}

func templateDependencies(node parse.Node) []string {
	var dependencies []string
	var walk func(parse.Node)
	walk = func(current parse.Node) {
		switch value := current.(type) {
		case *parse.ListNode:
			if value != nil {
				for _, child := range value.Nodes {
					walk(child)
				}
			}
		case *parse.TemplateNode:
			dependencies = append(dependencies, value.Name)
		case *parse.IfNode:
			walk(value.List)
			walk(value.ElseList)
		case *parse.RangeNode:
			walk(value.List)
			walk(value.ElseList)
		case *parse.WithNode:
			walk(value.List)
			walk(value.ElseList)
		}
	}
	walk(node)
	return dependencies
}

type routeMatch struct {
	name   string
	params []string
	known  bool
	api    bool
	static bool
}

func (h *handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	match := matchRoute(r.URL.Path)
	if !match.known {
		if match.api {
			h.writeError(w, r, http.StatusNotFound, "not_found", "The requested resource was not found.")
		} else {
			h.renderError(w, r, http.StatusNotFound, "Page not found", "The requested page was not found.")
		}
		return
	}
	allowed := allowedMethods(match)
	if !methodAllowed(r.Method, allowed) {
		w.Header().Set("Allow", strings.Join(allowed, ", "))
		h.writeRouteError(w, r, match.api, http.StatusMethodNotAllowed, "method_not_allowed", "The method is not supported for this resource.")
		return
	}
	if r.Method == http.MethodHead {
		w = headResponseWriter{ResponseWriter: w}
	}
	if match.static {
		h.serveStatic(w, r, match.params[0])
		return
	}
	h.dispatch(w, r, match)
}

func allowedMethods(match routeMatch) []string {
	switch match.name {
	case "api_operation_prepare":
		return []string{http.MethodPost}
	case "api_operations":
		return []string{http.MethodGet, http.MethodHead, http.MethodPost}
	case "operation_prepare", "operation_start", "operation_cancel", "run_cancel", "sprint_create":
		return []string{http.MethodPost}
	case "api_operation":
		return []string{http.MethodGet, http.MethodDelete}
	case "api_operation_events":
		return []string{http.MethodGet}
	case "api_run":
		return []string{http.MethodGet, http.MethodHead, http.MethodDelete}
	case "api_run_events":
		return []string{http.MethodGet, http.MethodHead}
	default:
		return []string{http.MethodGet, http.MethodHead}
	}
}

func methodAllowed(method string, allowed []string) bool {
	for _, candidate := range allowed {
		if method == candidate {
			return true
		}
	}
	return false
}

func matchRoute(path string) routeMatch {
	if path == "/" {
		return routeMatch{name: "dashboard", known: true}
	}
	if path == "/projects" {
		return routeMatch{name: "projects", known: true}
	}
	if path == "/studies" {
		return routeMatch{name: "studies", known: true}
	}
	if path == "/runs" {
		return routeMatch{name: "runs", known: true}
	}
	if path == "/api/v1/dashboard" {
		return routeMatch{name: "api_dashboard", known: true, api: true}
	}
	if path == "/api/v1/projects" {
		return routeMatch{name: "api_projects", known: true, api: true}
	}
	if path == "/api/v1/studies" {
		return routeMatch{name: "api_studies", known: true, api: true}
	}
	if path == "/api/v1/validations" {
		return routeMatch{name: "api_validations", known: true, api: true}
	}
	if path == "/api/v1/models" {
		return routeMatch{name: "api_models", known: true, api: true}
	}
	if path == "/api/v1/health" {
		return routeMatch{name: "api_health", known: true, api: true}
	}
	if path == "/api/v1/operations/prepare" {
		return routeMatch{name: "api_operation_prepare", known: true, api: true}
	}
	if path == "/api/v1/operations" {
		return routeMatch{name: "api_operations", known: true, api: true}
	}
	if path == "/api/v1/runs" {
		return routeMatch{name: "api_runs", known: true, api: true}
	}
	if path == "/api/v1/timeline" {
		return routeMatch{name: "api_timeline", known: true, api: true}
	}
	if path == "/operations/prepare" {
		return routeMatch{name: "operation_prepare", known: true}
	}
	if path == "/operations/start" {
		return routeMatch{name: "operation_start", known: true}
	}
	parts := splitPath(path)
	switch {
	case len(parts) == 4 && parts[0] == "projects" && (parts[2] == "documentation" || parts[2] == "artifacts"):
		return routeMatch{name: "project_artifact", params: []string{parts[1], parts[3]}, known: true}
	case len(parts) == 6 && parts[0] == "projects" && parts[2] == "sprints" && parts[4] == "artifacts":
		return routeMatch{name: "sprint_artifact", params: []string{parts[1], parts[3], parts[5]}, known: true}
	case len(parts) == 5 && parts[0] == "projects" && parts[2] == "sprints" && parts[4] == "qa":
		return routeMatch{name: "sprint_qa", params: []string{parts[1], parts[3]}, known: true}
	case len(parts) == 7 && parts[0] == "projects" && parts[2] == "sprints" && parts[4] == "qa" && parts[5] == "shards":
		return routeMatch{name: "sprint_qa_shard", params: []string{parts[1], parts[3], parts[6]}, known: true}
	case len(parts) == 7 && parts[0] == "projects" && parts[2] == "sprints" && parts[4] == "qa" && parts[5] == "theories":
		return routeMatch{name: "sprint_qa_theory", params: []string{parts[1], parts[3], parts[6]}, known: true}
	case len(parts) == 3 && parts[0] == "projects" && validProjectPage(parts[2]):
		return routeMatch{name: "project_page", params: []string{parts[1], parts[2]}, known: true}
	case len(parts) == 2 && parts[0] == "projects":
		return routeMatch{name: "project", params: parts[1:], known: true}
	case len(parts) == 5 && parts[0] == "projects" && parts[2] == "sprints" && validSprintPage(parts[4]):
		return routeMatch{name: "sprint_page", params: []string{parts[1], parts[3], parts[4]}, known: true}
	case len(parts) == 4 && parts[0] == "projects" && parts[2] == "sprints" && parts[3] == "create":
		return routeMatch{name: "sprint_create", params: []string{parts[1]}, known: true}
	case len(parts) == 4 && parts[0] == "projects" && parts[2] == "sprints":
		return routeMatch{name: "sprint", params: []string{parts[1], parts[3]}, known: true}
	case len(parts) == 3 && parts[0] == "studies" && validStudyPage(parts[2]):
		return routeMatch{name: "study_page", params: []string{parts[1], parts[2]}, known: true}
	case len(parts) == 2 && parts[0] == "studies":
		return routeMatch{name: "study", params: parts[1:], known: true}
	case len(parts) == 2 && parts[0] == "artifacts":
		return routeMatch{name: "artifact", params: parts[1:], known: true}
	case len(parts) == 2 && parts[0] == "operations":
		return routeMatch{name: "operation", params: parts[1:], known: true}
	case len(parts) == 2 && parts[0] == "runs":
		return routeMatch{name: "run", params: parts[1:], known: true}
	case len(parts) == 3 && parts[0] == "runs" && parts[2] == "cancel":
		return routeMatch{name: "run_cancel", params: []string{parts[1]}, known: true}
	case len(parts) == 3 && parts[0] == "operations" && parts[2] == "cancel":
		return routeMatch{name: "operation_cancel", params: []string{parts[1]}, known: true}
	case len(parts) == 4 && parts[0] == "api" && parts[1] == "v1" && parts[2] == "projects":
		return routeMatch{name: "api_project", params: parts[3:], known: true, api: true}
	case len(parts) == 6 && parts[0] == "api" && parts[1] == "v1" && parts[2] == "projects" && parts[4] == "sprints":
		return routeMatch{name: "api_sprint", params: []string{parts[3], parts[5]}, known: true, api: true}
	case len(parts) == 7 && parts[0] == "api" && parts[1] == "v1" && parts[2] == "projects" && parts[4] == "sprints" && parts[6] == "qa":
		return routeMatch{name: "api_sprint_qa", params: []string{parts[3], parts[5]}, known: true, api: true}
	case len(parts) == 8 && parts[0] == "api" && parts[1] == "v1" && parts[2] == "projects" && parts[4] == "sprints" && parts[6] == "qa" && (parts[7] == "map" || parts[7] == "synthesis"):
		return routeMatch{name: "api_sprint_qa_" + parts[7], params: []string{parts[3], parts[5]}, known: true, api: true}
	case len(parts) == 9 && parts[0] == "api" && parts[1] == "v1" && parts[2] == "projects" && parts[4] == "sprints" && parts[6] == "qa" && parts[7] == "shards":
		return routeMatch{name: "api_sprint_qa_shard", params: []string{parts[3], parts[5], parts[8]}, known: true, api: true}
	case len(parts) == 9 && parts[0] == "api" && parts[1] == "v1" && parts[2] == "projects" && parts[4] == "sprints" && parts[6] == "qa" && parts[7] == "theories":
		return routeMatch{name: "api_sprint_qa_theory", params: []string{parts[3], parts[5], parts[8]}, known: true, api: true}
	case len(parts) == 8 && parts[0] == "api" && parts[1] == "v1" && parts[2] == "projects" && parts[4] == "sprints" && parts[6] == "prompts":
		return routeMatch{name: "api_prompt_bundle", params: []string{parts[3], parts[5], parts[7]}, known: true, api: true}
	case len(parts) == 4 && parts[0] == "api" && parts[1] == "v1" && parts[2] == "studies":
		return routeMatch{name: "api_study", params: parts[3:], known: true, api: true}
	case len(parts) == 5 && parts[0] == "api" && parts[1] == "v1" && parts[2] == "studies" && parts[4] == "resources":
		return routeMatch{name: "api_study_resources", params: []string{parts[3]}, known: true, api: true}
	case len(parts) == 4 && parts[0] == "api" && parts[1] == "v1" && parts[2] == "artifacts":
		return routeMatch{name: "api_artifact", params: parts[3:], known: true, api: true}
	case len(parts) == 4 && parts[0] == "api" && parts[1] == "v1" && parts[2] == "operations":
		return routeMatch{name: "api_operation", params: parts[3:], known: true, api: true}
	case len(parts) == 5 && parts[0] == "api" && parts[1] == "v1" && parts[2] == "operations" && parts[4] == "events":
		return routeMatch{name: "api_operation_events", params: []string{parts[3]}, known: true, api: true}
	case len(parts) == 4 && parts[0] == "api" && parts[1] == "v1" && parts[2] == "runs":
		return routeMatch{name: "api_run", params: parts[3:], known: true, api: true}
	case len(parts) == 5 && parts[0] == "api" && parts[1] == "v1" && parts[2] == "runs" && parts[4] == "events":
		return routeMatch{name: "api_run_events", params: []string{parts[3]}, known: true, api: true}
	case strings.HasPrefix(path, "/static/"):
		name := strings.TrimPrefix(path, "/static/")
		if _, ok := staticAssetNames[name]; ok {
			return routeMatch{name: "static", params: []string{name}, known: true, static: true}
		}
	}
	return routeMatch{api: strings.HasPrefix(path, "/api/")}
}

func validProjectPage(page string) bool {
	switch page {
	case "roadmap", "sprints", "documentation", "artifacts", "operations", "validation":
		return true
	default:
		return false
	}
}

func validSprintPage(page string) bool {
	switch page {
	case "workflow", "run", "artifacts", "plan", "delivery", "operations", "validation":
		return true
	default:
		return false
	}
}

func validStudyPage(page string) bool {
	switch page {
	case "inputs", "progress", "results", "operations", "validation", "dimensions", "reports", "repos":
		return true
	default:
		return false
	}
}

func splitPath(path string) []string {
	if path == "" || path == "/" || strings.HasSuffix(path, "/") {
		return nil
	}
	return strings.Split(strings.TrimPrefix(path, "/"), "/")
}

type headResponseWriter struct{ http.ResponseWriter }

func (w headResponseWriter) Write(data []byte) (int, error) { return len(data), nil }

func (h *handler) serveStatic(w http.ResponseWriter, _ *http.Request, name string) {
	data, err := assets.ReadFile("static/" + name)
	if err != nil {
		http.Error(w, "static asset unavailable", http.StatusInternalServerError)
		return
	}
	if strings.HasSuffix(name, ".css") {
		w.Header().Set("Content-Type", "text/css; charset=utf-8")
	} else {
		w.Header().Set("Content-Type", "text/javascript; charset=utf-8")
	}
	w.Header().Set("Cache-Control", "public, max-age=0, must-revalidate")
	w.Header().Set("Content-Length", strconv.Itoa(len(data)))
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(data)
}

package web

import (
	"context"
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/app"
)

const (
	MaxBodyBytes       = 64 * 1024
	MaxRequestTarget   = 8 * 1024
	MaxIdentifierBytes = 128
)

type requestIDKey struct{}
type sessionIDKey struct{}
type csrfTokenKey struct{}

type trackedWriter struct {
	http.ResponseWriter
	status int
	bytes  int
}

func (w *trackedWriter) Unwrap() http.ResponseWriter { return w.ResponseWriter }

func (w *trackedWriter) WriteHeader(status int) {
	if w.status != 0 {
		return
	}
	w.status = status
	w.ResponseWriter.WriteHeader(status)
}

func (w *trackedWriter) Write(data []byte) (int, error) {
	if w.status == 0 {
		w.WriteHeader(http.StatusOK)
	}
	n, err := w.ResponseWriter.Write(data)
	w.bytes += n
	return n, err
}

func (w *trackedWriter) Flush() {
	if w.status == 0 {
		w.WriteHeader(http.StatusOK)
	}
	if flusher, ok := w.ResponseWriter.(http.Flusher); ok {
		flusher.Flush()
	}
}

type securityMiddleware struct {
	authority   string
	origin      string
	diagnostics io.Writer
	now         func() time.Time
	requestID   func() string
	sem         chan struct{}
	active      atomic.Int64
	secret      [32]byte
}

func newSecurityMiddleware(authority string, diagnostics io.Writer, now func() time.Time, requestID func() string) *securityMiddleware {
	if diagnostics == nil {
		diagnostics = io.Discard
	}
	if now == nil {
		now = time.Now
	}
	if requestID == nil {
		requestID = randomRequestID
	}
	m := &securityMiddleware{
		authority:   authority,
		origin:      "http://" + authority,
		diagnostics: diagnostics,
		now:         now,
		requestID:   requestID,
		sem:         make(chan struct{}, MaxInFlight),
	}
	if _, err := rand.Read(m.secret[:]); err != nil {
		m.secret = sha256.Sum256([]byte(authority + now().UTC().Format(time.RFC3339Nano)))
	}
	return m
}

func (m *securityMiddleware) wrap(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		started := m.now()
		tracked := &trackedWriter{ResponseWriter: w}
		applySecurityHeaders(tracked.Header())
		id := m.requestID()
		tracked.Header().Set("X-Request-ID", id)
		r = r.WithContext(context.WithValue(r.Context(), requestIDKey{}, id))
		session, validSession := m.readSession(r)
		if !validSession {
			session = randomRequestID()
			http.SetCookie(tracked, &http.Cookie{Name: "ultraplan_session", Value: m.signSession(session), Path: "/", HttpOnly: true, SameSite: http.SameSiteStrictMode, MaxAge: 3600})
		}
		csrf := m.csrfFor(session)
		tracked.Header().Set("X-CSRF-Token", csrf)
		ctx := context.WithValue(r.Context(), sessionIDKey{}, session)
		ctx = context.WithValue(ctx, csrfTokenKey{}, csrf)
		r = r.WithContext(ctx)

		select {
		case m.sem <- struct{}{}:
			m.active.Add(1)
			defer func() {
				m.active.Add(-1)
				<-m.sem
			}()
		case <-r.Context().Done():
			m.reject(tracked, r, http.StatusServiceUnavailable, "unavailable", "The service is unavailable.")
			return
		}

		matchedRoute := matchRoute(r.URL.Path)
		apiOperationMutation := (r.Method == http.MethodPost || r.Method == http.MethodDelete) && strings.HasPrefix(r.URL.Path, "/api/v1/operations")
		apiRunMutation := r.Method == http.MethodDelete && matchedRoute.name == "api_run"
		htmlOperationMutation := r.Method == http.MethodPost && strings.HasPrefix(r.URL.Path, "/operations/")
		htmlSprintMutation := r.Method == http.MethodPost && matchedRoute.name == "sprint_create"
		htmlRunMutation := r.Method == http.MethodPost && matchedRoute.name == "run_cancel"
		operationMutation := apiOperationMutation || apiRunMutation || htmlOperationMutation || htmlSprintMutation || htmlRunMutation
		operationRead := (r.Method == http.MethodGet || r.Method == http.MethodHead) && (matchedRoute.name == "api_operation" || matchedRoute.name == "api_operation_events")
		staticAsset := (r.Method == http.MethodGet || r.Method == http.MethodHead) && strings.HasPrefix(r.URL.Path, "/static/")
		hasBody := r.ContentLength > 0 || len(r.TransferEncoding) > 0
		operationBody := r.Method == http.MethodPost && (matchedRoute.name == "api_operation_prepare" || matchedRoute.name == "api_operations" || matchedRoute.name == "operation_prepare" || matchedRoute.name == "operation_start" || matchedRoute.name == "operation_cancel" || matchedRoute.name == "run_cancel" || matchedRoute.name == "sprint_create")
		switch {
		case len(r.RequestURI) > MaxRequestTarget:
			m.reject(tracked, r, http.StatusBadRequest, "invalid_request", "The request target is too long.")
		case ambiguousRequestFraming(r):
			m.reject(tracked, r, http.StatusBadRequest, "invalid_request", "The request framing is ambiguous.")
		case r.Host != m.authority:
			m.reject(tracked, r, http.StatusForbidden, "host_rejected", hostRejectionMessage(m.authority, r.Host))
		case operationMutation && !validSession:
			m.reject(tracked, r, http.StatusForbidden, "session_required", "Establish a browser session before submitting commands.")
		case operationMutation && !validCommandRequestOrigin(r, m.origin):
			m.reject(tracked, r, http.StatusForbidden, "origin_rejected", originRejectionMessage(m.origin, r.Header.Get("Origin")))
		case (apiOperationMutation || apiRunMutation) && subtle.ConstantTimeCompare([]byte(r.Header.Get("X-CSRF-Token")), []byte(csrf)) != 1:
			m.reject(tracked, r, http.StatusForbidden, "csrf_failed", "The CSRF proof did not match this browser session. Refresh the UltraPlan page and prepare the operation again.")
		case operationRead && !validOperationReadRequestOrigin(r, m.origin):
			m.reject(tracked, r, http.StatusForbidden, "origin_rejected", originRejectionMessage(m.origin, r.Header.Get("Origin")))
		case !operationMutation && !operationRead && !staticAsset && !validReadRequestOrigin(r, m.origin):
			m.reject(tracked, r, http.StatusForbidden, "origin_rejected", originRejectionMessage(m.origin, r.Header.Get("Origin")))
		case r.ContentLength > MaxBodyBytes:
			m.reject(tracked, r, http.StatusRequestEntityTooLarge, "request_too_large", "The request is too large.")
		case hasBody && !operationBody:
			m.reject(tracked, r, http.StatusBadRequest, "invalid_request", "Request bodies are not accepted.")
		default:
			if operationBody {
				r.Body = http.MaxBytesReader(tracked, r.Body, MaxBodyBytes)
			}
			next.ServeHTTP(tracked, r)
		}
		if tracked.status == 0 {
			tracked.status = http.StatusOK
		}
		fmt.Fprintf(m.diagnostics,
			"event=http_request request_id=%s route=%s method=%s status=%d duration_ms=%d response_bytes=%d\n",
			id, normalizedRoute(r.URL.Path), r.Method, tracked.status, m.now().Sub(started).Milliseconds(), tracked.bytes)
	})
}

func ambiguousRequestFraming(r *http.Request) bool {
	contentLengths := r.Header.Values("Content-Length")
	return len(contentLengths) > 1 || (len(contentLengths) > 0 && len(r.TransferEncoding) > 0)
}

func (m *securityMiddleware) reject(w http.ResponseWriter, r *http.Request, status int, code, message string) {
	fmt.Fprintf(m.diagnostics, "event=security_rejection request_id=%s route=%s method=%s status=%d code=%s\n", requestID(r.Context()), normalizedRoute(r.URL.Path), r.Method, status, code)
	writePolicyError(w, r, status, code, message)
}

func originRejectionMessage(expected, received string) string {
	return fmt.Sprintf("The browser sent the request from %s, but this server only accepts commands from %s. Open the exact Dashboard URL printed by UltraPlan, refresh it, and retry.", displayOrigin(received), expected)
}

func hostRejectionMessage(expected, received string) string {
	return fmt.Sprintf("The request used host %s, but this server is listening as %s. Open the exact Dashboard URL printed by UltraPlan.", displayAuthority(received), expected)
}

func displayOrigin(value string) string {
	if value == "" {
		return "a request with no Origin header"
	}
	if value == "null" {
		return "the opaque origin 'null'"
	}
	parsed, err := url.Parse(value)
	if err != nil || parsed.Scheme == "" || parsed.Host == "" || parsed.User != nil {
		return "an invalid origin"
	}
	return parsed.Scheme + "://" + displayAuthority(parsed.Host)
}

func displayAuthority(value string) string {
	value = strings.Map(func(r rune) rune {
		if r < 0x20 || r == 0x7f {
			return -1
		}
		return r
	}, value)
	if len(value) > 256 {
		value = value[:256] + "…"
	}
	if value == "" {
		return "an empty host"
	}
	return value
}

func (m *securityMiddleware) signSession(session string) string {
	mac := hmac.New(sha256.New, m.secret[:])
	_, _ = mac.Write([]byte("session:" + session))
	return session + "." + hex.EncodeToString(mac.Sum(nil))
}

func (m *securityMiddleware) readSession(r *http.Request) (string, bool) {
	cookie, err := r.Cookie("ultraplan_session")
	if err != nil {
		return "", false
	}
	parts := strings.Split(cookie.Value, ".")
	if len(parts) != 2 || len(parts[0]) != 32 {
		return "", false
	}
	expected := m.signSession(parts[0])
	return parts[0], subtle.ConstantTimeCompare([]byte(cookie.Value), []byte(expected)) == 1
}

func (m *securityMiddleware) csrfFor(session string) string {
	mac := hmac.New(sha256.New, m.secret[:])
	_, _ = mac.Write([]byte("csrf:" + session))
	return hex.EncodeToString(mac.Sum(nil))
}

func applySecurityHeaders(header http.Header) {
	header.Set("Cache-Control", "no-store")
	header.Set("Content-Security-Policy", "default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; object-src 'none'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'")
	header.Set("Referrer-Policy", "same-origin")
	header.Set("X-Content-Type-Options", "nosniff")
	header.Set("X-Frame-Options", "DENY")
	header.Set("Permissions-Policy", "camera=(), microphone=(), geolocation=()")
}

func validOrigin(origin, expected string) bool {
	if origin == "" {
		return true
	}
	return validCommandOrigin(origin, expected)
}

// validCommandOrigin permits a browser shell or local reverse proxy to omit or
// rewrite only the port while preserving the exact numeric loopback address.
// Mutating requests still require the signed session and CSRF proof.
func validCommandOrigin(origin, expected string) bool {
	return origin == expected
}

// validCommandRequestOrigin accepts the exact configured origin. It also
// tolerates browsers that remove a non-default port from Origin when their
// unforgeable fetch metadata and exact Referer still prove a same-origin
// request. Session and CSRF validation remain separate mandatory checks.
func validCommandRequestOrigin(r *http.Request, expected string) bool {
	if validCommandOrigin(r.Header.Get("Origin"), expected) {
		return true
	}
	if r.Header.Get("Sec-Fetch-Site") != "same-origin" {
		return false
	}
	receivedURL, receivedErr := url.Parse(r.Header.Get("Origin"))
	expectedURL, expectedErr := url.Parse(expected)
	refererURL, refererErr := url.Parse(r.Header.Get("Referer"))
	if receivedErr != nil || expectedErr != nil || refererErr != nil ||
		receivedURL.User != nil || expectedURL.User != nil || refererURL.User != nil {
		return false
	}
	return receivedURL.Scheme == expectedURL.Scheme &&
		receivedURL.Hostname() == expectedURL.Hostname() &&
		receivedURL.Port() == "" && expectedURL.Port() != "" &&
		refererURL.Scheme+"://"+refererURL.Host == expected
}

func validOperationReadOrigin(origin, expected string) bool {
	return origin == "" || validCommandOrigin(origin, expected)
}

func validOperationReadRequestOrigin(r *http.Request, expected string) bool {
	return r.Header.Get("Origin") == "" || validCommandRequestOrigin(r, expected)
}

// validReadRequestOrigin applies the browser's same-origin proofs to ordinary
// read-only pages and APIs too. Some browser shells normalize a loopback
// Origin by dropping its non-default port, even though Host and Referer retain
// the exact authority. Mutations continue through the stricter command path.
func validReadRequestOrigin(r *http.Request, expected string) bool {
	return r.Header.Get("Origin") == "" || validCommandRequestOrigin(r, expected)
}

func requestID(ctx context.Context) string {
	id, _ := ctx.Value(requestIDKey{}).(string)
	return id
}

func sessionID(ctx context.Context) string {
	id, _ := ctx.Value(sessionIDKey{}).(string)
	return id
}

func csrfToken(ctx context.Context) string {
	token, _ := ctx.Value(csrfTokenKey{}).(string)
	return token
}

func randomRequestID() string {
	var data [16]byte
	if _, err := rand.Read(data[:]); err != nil {
		return "00000000000000000000000000000000"
	}
	return hex.EncodeToString(data[:])
}

func normalizedRoute(path string) string {
	switch {
	case path == "/":
		return "dashboard"
	case path == "/projects":
		return "projects"
	case strings.HasPrefix(path, "/projects/") && strings.Contains(path, "/sprints/"):
		return "sprint_detail"
	case strings.HasPrefix(path, "/projects/"):
		return "project_detail"
	case path == "/studies":
		return "studies"
	case strings.HasPrefix(path, "/studies/"):
		return "study_detail"
	case strings.HasPrefix(path, "/artifacts/"):
		return "artifact"
	case strings.HasPrefix(path, "/api/v1/artifacts/"):
		return "api_artifact"
	case strings.HasPrefix(path, "/api/v1/"):
		return "api_v1"
	case strings.HasPrefix(path, "/api/"):
		return "api_unknown"
	case strings.HasPrefix(path, "/static/"):
		return "static"
	default:
		return "not_found"
	}
}

type preparationRecord struct {
	ID           string
	Token        string
	Session      string
	Canonical    string
	Fingerprint  string
	Confirmation app.Confirmation
	ExpiresAt    time.Time
	Consumed     bool
}

type preparationStore struct {
	mu      sync.Mutex
	now     func() time.Time
	id      func() string
	records map[string]*preparationRecord
}

func newPreparationStore(now func() time.Time, id func() string) *preparationStore {
	if now == nil {
		now = time.Now
	}
	if id == nil {
		id = randomRequestID
	}
	return &preparationStore{now: now, id: id, records: make(map[string]*preparationRecord)}
}

func (s *preparationStore) issue(session string, confirmation app.Confirmation) (*preparationRecord, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.reapLocked()
	if len(s.records) >= MaxPreparations {
		return nil, errOperationCapacity
	}
	record := &preparationRecord{
		ID: "prep_" + s.id(), Token: "confirm_" + s.id(), Session: session,
		Canonical: confirmation.CanonicalRequest, Fingerprint: confirmation.InputFingerprint,
		Confirmation: confirmation, ExpiresAt: s.now().UTC().Add(PreparationTTL),
	}
	s.records[record.Token] = record
	copy := *record
	return &copy, nil
}

func (s *preparationStore) consume(token, session, canonical, fingerprint string) (app.Confirmation, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	record := s.records[token]
	if record == nil {
		return app.Confirmation{}, errConfirmationReplayed
	}
	if record.Consumed {
		return app.Confirmation{}, errConfirmationReplayed
	}
	if !s.now().UTC().Before(record.ExpiresAt) {
		record.Consumed = true
		return app.Confirmation{}, errConfirmationExpired
	}
	if record.Session != session || record.Canonical != canonical {
		record.Consumed = true
		return app.Confirmation{}, errConfirmationMismatch
	}
	if record.Fingerprint != fingerprint {
		record.Consumed = true
		return app.Confirmation{}, errStaleConfirmation
	}
	record.Consumed = true
	return record.Confirmation, nil
}

func (s *preparationStore) reapLocked() {
	now := s.now().UTC()
	for token, record := range s.records {
		if !now.Before(record.ExpiresAt) {
			delete(s.records, token)
		}
	}
}

func confirmationDedupKey(session, token string) string {
	digest := sha256.Sum256([]byte(session + "\x00" + token))
	return hex.EncodeToString(digest[:])
}

var (
	errConfirmationExpired  = errors.New("confirmation expired")
	errConfirmationMismatch = errors.New("confirmation mismatch")
	errConfirmationReplayed = errors.New("confirmation replayed")
	errStaleConfirmation    = errors.New("stale confirmation")
)

package web

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"sync"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/app"
)

const (
	ReadHeaderTimeout = 5 * time.Second
	ReadTimeout       = 15 * time.Second
	WriteTimeout      = 30 * time.Second
	IdleTimeout       = 60 * time.Second
	ShutdownTimeout   = 10 * time.Second
	MaxInFlight       = 32
)

type Options struct {
	Listen        string
	OpenBrowser   bool
	Queries       app.WebQueries
	Operations    app.WebOperations
	Runs          app.RunUseCases
	Stdout        io.Writer
	Diagnostics   io.Writer
	ListenFunc    func(string, string) (net.Listener, error)
	LaunchBrowser func(context.Context, string) error
	Now           func() time.Time
	RequestID     func() string
}

func Run(ctx context.Context, opts Options) error {
	if ctx == nil {
		ctx = context.Background()
	}
	if err := app.ValidateLoopbackListen(opts.Listen); err != nil {
		return fmt.Errorf("validate listen address: %w", err)
	}
	if err := ValidateServerPolicy(DefaultServerPolicy()); err != nil {
		return fmt.Errorf("validate local-web policy: %w", err)
	}
	if opts.Queries == nil {
		return errors.New("web queries are required")
	}
	if opts.Stdout == nil {
		opts.Stdout = io.Discard
	}
	if opts.Diagnostics == nil {
		opts.Diagnostics = io.Discard
	}
	diagnostics := &lockedWriter{writer: opts.Diagnostics}
	if opts.ListenFunc == nil {
		opts.ListenFunc = net.Listen
	}

	listener, err := opts.ListenFunc("tcp", opts.Listen)
	if err != nil {
		return fmt.Errorf("listen on configured loopback address: %w", err)
	}
	defer listener.Close()
	authority, err := canonicalAuthority(listener.Addr())
	if err != nil {
		return err
	}
	if err := app.ValidateLoopbackListen(authority); err != nil {
		return fmt.Errorf("listener resolved outside loopback policy: %w", err)
	}
	origin := "http://" + authority
	if reconciler, ok := opts.Operations.(app.OperationReconciler); ok {
		if err := reconciler.ReconcileOperations(ctx); err != nil {
			_ = listener.Close()
			return fmt.Errorf("reconcile interrupted operations: %w", err)
		}
	}

	operationRoot, cancelOperations := context.WithCancel(context.Background())
	defer cancelOperations()
	hub := newOperationHub(operationRoot, opts.Operations, opts.Now, opts.RequestID)
	handler, err := NewHandler(HandlerOptions{
		Queries:     opts.Queries,
		Operations:  opts.Operations,
		Runs:        opts.Runs,
		Authority:   authority,
		Diagnostics: diagnostics,
		Now:         opts.Now,
		RequestID:   opts.RequestID,
		RootContext: operationRoot,
		Hub:         hub,
	})
	if err != nil {
		return fmt.Errorf("initialize web presentation: %w", err)
	}
	server := &http.Server{
		Handler:           handler,
		ReadHeaderTimeout: ReadHeaderTimeout,
		ReadTimeout:       ReadTimeout,
		WriteTimeout:      WriteTimeout,
		IdleTimeout:       IdleTimeout,
		BaseContext:       func(net.Listener) context.Context { return ctx },
	}

	if _, err := fmt.Fprintf(opts.Stdout, "Dashboard: %s/\n", origin); err != nil {
		return fmt.Errorf("write dashboard URL: %w", err)
	}
	serveErr := make(chan error, 1)
	go func() {
		serveErr <- server.Serve(listener)
	}()
	fmt.Fprintf(diagnostics, "event=server_started listen=%s\n", authority)
	if opts.OpenBrowser {
		if opts.LaunchBrowser == nil {
			fmt.Fprintln(diagnostics, "event=browser_launch warning=launcher_unavailable")
		} else if err := opts.LaunchBrowser(ctx, origin+"/"); err != nil {
			fmt.Fprintln(diagnostics, "event=browser_launch warning=launch_failed")
		}
	}

	select {
	case err := <-serveErr:
		if errors.Is(err, http.ErrServerClosed) {
			return nil
		}
		return fmt.Errorf("serve HTTP: %w", err)
	case <-ctx.Done():
		started := time.Now()
		shutdownCtx, cancel := context.WithTimeout(context.Background(), ShutdownTimeout)
		defer cancel()
		cleanupErr := hub.drainAndWait(shutdownCtx)
		cancelOperations()
		err := server.Shutdown(shutdownCtx)
		if cleanupErr != nil {
			return fmt.Errorf("operation cleanup during shutdown: %w", cleanupErr)
		}
		if err != nil {
			_ = server.Close()
		}
		serveResult := <-serveErr
		fmt.Fprintf(diagnostics, "event=server_stopped reason=cancelled duration_ms=%d\n", time.Since(started).Milliseconds())
		if err != nil {
			return fmt.Errorf("graceful shutdown: %w", err)
		}
		if serveResult != nil && !errors.Is(serveResult, http.ErrServerClosed) {
			return fmt.Errorf("serve HTTP during shutdown: %w", serveResult)
		}
		return nil
	}
}

type lockedWriter struct {
	mu     sync.Mutex
	writer io.Writer
}

func (w *lockedWriter) Write(data []byte) (int, error) {
	w.mu.Lock()
	defer w.mu.Unlock()
	return w.writer.Write(data)
}

func canonicalAuthority(addr net.Addr) (string, error) {
	host, port, err := net.SplitHostPort(addr.String())
	if err != nil {
		return "", fmt.Errorf("resolve listener authority: %w", err)
	}
	ip := net.ParseIP(host)
	if ip == nil || !ip.IsLoopback() {
		return "", errors.New("listener is not a numeric loopback address")
	}
	return net.JoinHostPort(ip.String(), port), nil
}

package web

import (
	"errors"

	"github.com/Antonio7098/ultraplan-go/internal/app"
)

func validateArtifact(result app.WebArtifactPreview) error {
	if result.MediaType != "text/markdown" && result.MediaType != "application/json" {
		return errors.New("unsupported artifact media type")
	}
	if result.ReturnedBytes < 0 || result.ReturnedBytes > app.WebPreviewByteLimit ||
		len([]byte(result.Content)) != result.ReturnedBytes || result.SizeBytes < int64(result.ReturnedBytes) {
		return errors.New("invalid artifact size contract")
	}
	if result.Truncated != (result.SizeBytes > int64(result.ReturnedBytes)) {
		return errors.New("invalid artifact truncation contract")
	}
	return nil
}

